<?php

declare(strict_types=1);

$rich=static fn(mixed$value):string=>\App\Core\HtmlSanitizer::sanitize((string)$value);
$heading=static function(array$data)use($e,$rich):string{$html='<header class="school-block-heading">';if(!empty($data['eyebrow']))$html.='<p class="school-eyebrow">'.$e($data['eyebrow']).'</p>';if(!empty($data['title']))$html.='<h2>'.$e($data['title']).'</h2>';if(!empty($data['text']))$html.='<div class="school-rich-copy">'.$rich($data['text']).'</div>';return$html.'</header>';};
$action=static function(mixed$label,mixed$url,string$class='school-button')use($e,$safeUrl):string{$label=trim((string)$label);$url=trim((string)$url);return$label!==''&&$safeUrl($url)?'<a class="'.$class.'" href="'.$e($url).'">'.$e($label).'<span aria-hidden="true">→</span></a>':'';};
$image=static function(mixed$src,mixed$alt='')use($e,$safeUrl):string{return$safeUrl($src)?'<img src="'.$e($src).'" alt="'.$e($alt).'" loading="lazy">':'';};
foreach((array)($page['blocks']??[])as$block):$type=(string)($block['type']??'');$data=(array)($block['payload']??[]);$shared=(array)($block['shared']??[]);
if($type==='separator'):?><div class="school-separator" style="--school-space:<?=max(0,min(240,(int)($shared['spacing']??48)))?>px"><hr class="is-<?= $e(in_array($shared['style']??'', ['solid','dashed','dotted'],true)?$shared['style']:'solid') ?>" style="border-width:<?=max(1,min(8,(int)($shared['weight']??1)))?>px"></div><?php continue;endif;
if($type==='spacer'):?><div class="school-spacer" aria-hidden="true" style="--school-spacer:<?=max(0,min(480,(int)($shared['desktop']??96)))?>px"></div><?php continue;endif;
if($type==='custom-html'):?><section class="school-block school-custom"><div class="school-shell"><?= $rich($data['html']??'') ?></div></section><?php continue;endif;
if($type==='contact-form'&&!empty($formCsrf)):$formUid=(string)($block['uid']??'');if(!preg_match('/^[a-f0-9-]{36}$/iD',$formUid))continue;$captcha=!empty($shared['captcha'])&&!empty($formCaptchaEnabled);?><section class="school-block school-contact"><div class="school-shell school-contact-grid"><div><?= $heading($data) ?></div><form action="/api/forms/<?= $e($formUid) ?>/submit" method="post" data-school-form><input type="hidden" name="csrf" value="<?= $e($formCsrf) ?>"><input type="hidden" name="locale" value="<?= $e($locale) ?>"><div class="school-trap" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><?php foreach((array)($data['fields']??[])as$field):$field=(array)$field;$key=(string)($field['key']??'');$fieldType=(string)($field['type']??'text');if(!preg_match('/^[a-z][a-z0-9_]{1,39}$/D',$key))continue;$id='school-'.$formUid.'-'.$key;?><label<?= $fieldType==='textarea'?' class="is-wide"':'' ?>><span><?= $e($field['label']??$key) ?><?= !empty($field['required'])?' *':'' ?></span><?php if($fieldType==='textarea'):?><textarea id="<?= $e($id) ?>" name="fields[<?= $e($key) ?>]" rows="5" maxlength="5000" placeholder="<?= $e($field['placeholder']??'') ?>"<?= !empty($field['required'])?' required':'' ?>></textarea><?php elseif($fieldType==='select'):?><select id="<?= $e($id) ?>" name="fields[<?= $e($key) ?>]"<?= !empty($field['required'])?' required':'' ?>><option value="">—</option><?php foreach(array_filter(array_map('trim',preg_split('/\R/u',(string)($field['options']??''))?:[]))as$option):?><option value="<?= $e($option) ?>"><?= $e($option) ?></option><?php endforeach;?></select><?php elseif($fieldType==='checkbox'):?><span class="school-check"><input id="<?= $e($id) ?>" type="checkbox" name="fields[<?= $e($key) ?>]" value="1"<?= !empty($field['required'])?' required':'' ?>><?= $e($field['placeholder']??$field['label']??'') ?></span><?php else:?><input id="<?= $e($id) ?>" type="<?= in_array($fieldType,['email','tel'],true)?$fieldType:'text' ?>" name="fields[<?= $e($key) ?>]" maxlength="<?= $fieldType==='email'?190:500 ?>" placeholder="<?= $e($field['placeholder']??'') ?>"<?= !empty($field['required'])?' required':'' ?>><?php endif;?></label><?php endforeach;?><?php if($captcha):?><label class="is-wide"><span>Security code *</span><span class="school-captcha"><img src="/captcha/forms/<?= $e($formUid) ?>.png" width="180" height="52" alt="Security code" data-school-captcha><button type="button" data-school-captcha-refresh aria-label="Generate a new security code">↻</button><input name="captcha" maxlength="10" required autocomplete="off"></span></label><?php endif;?><div class="is-wide school-form-footer"><p><?= $e($data['privacy_text']??'') ?></p><button class="school-button" type="submit"><?= $e($data['submit_label']??'Send message') ?><span aria-hidden="true">→</span></button></div><p class="is-wide school-form-result" role="status" aria-live="polite" tabindex="-1" hidden></p></form></div></section><?php continue;endif;
if($type==='hero'):?><section class="school-hero"><div class="school-shell school-hero-grid"><div><?= $heading($data) ?><div class="school-action-row"><?= $action($data['primary_label']??'',$data['primary_url']??'') ?><?= $action($data['secondary_label']??'',$data['secondary_url']??'','school-text-link') ?></div></div><div class="school-hero-media"><?php if(($data['media_type']??'image')==='video'&&$safeUrl($data['video']??'')):?><video controls preload="metadata"<?= $safeUrl($data['poster']??'')?' poster="'.$e($data['poster']).'"':'' ?>><source src="<?= $e($data['video']) ?>"></video><?php else:?><?= $image($data['image']??'',$data['image_alt']??'') ?><?php endif;?></div></div></section><?php continue;endif;
if($type==='hero-slider'):?><section class="school-slider"><div class="school-shell"><?php foreach((array)($data['slides']??[])as$index=>$slide):$slide=(array)$slide;?><article<?= $index===0?' class="is-current"':' hidden' ?>><div><?= $heading($slide) ?><?= $action($slide['primary_label']??'',$slide['primary_url']??'') ?></div><?php if(($slide['media_type']??'image')==='video'&&$safeUrl($slide['video']??'')):?><video controls preload="metadata"><source src="<?= $e($slide['video']) ?>"></video><?php else:?><?= $image($slide['image']??'',$slide['alt']??'') ?><?php endif;?></article><?php endforeach;?></div></section><?php continue;endif;
if($type==='gallery'):?><section class="school-block"><div class="school-shell"><?= $heading($data) ?><div class="school-gallery"><?php foreach((array)($data['items']??[])as$item):$item=(array)$item;if(!$safeUrl($item['image']??''))continue;?><figure><?= $image($item['image'],$item['alt']??'') ?><?php if(!empty($item['title'])||!empty($item['eyebrow'])):?><figcaption><?php if(!empty($item['eyebrow'])):?><span><?= $e($item['eyebrow']) ?></span><?php endif;?><?= $e($item['title']??'') ?></figcaption><?php endif;?></figure><?php endforeach;?></div></div></section><?php continue;endif;
if($type==='admissions'):?><section class="school-block school-steps"><div class="school-shell"><?= $heading($data) ?><ol><?php foreach((array)($data['steps']??[])as$index=>$step):$step=(array)$step;?><li><span><?= $e(str_pad((string)($index+1),2,'0',STR_PAD_LEFT)) ?></span><div><h3><?= $e($step['title']??'') ?></h3><p><?= nl2br($e($step['text']??'')) ?></p><?= $action($step['label']??'',$step['url']??'','school-text-link') ?></div></li><?php endforeach;?></ol><?= $action($data['cta_label']??'',$data['cta_url']??'') ?></div></section><?php continue;endif;
if(!empty($block['component_renderer'])):?><section class="school-block"><div class="school-shell"><?= \App\Core\PluginComponentRenderer::render($projectRoot,(string)($block['component_source']??''),(string)$block['component_renderer'],['data'=>$data,'shared'=>$shared,'locale'=>$locale,'page'=>$page]) ?></div></section><?php continue;endif;?>
<section class="school-block school-block-<?= $e($type) ?>"><div class="school-shell school-generic-block"><?= $heading($data) ?><?php if($type==='image-text'&&$safeUrl($data['image']??'')):?><figure><?= $image($data['image'],$data['image_alt']??'') ?></figure><?php endif;?><?php if(!empty($data['items'])&&is_array($data['items'])):?><div class="school-cards"><?php foreach($data['items']as$item):$item=(array)$item;?><article><?php if(!empty($item['title'])):?><h3><?= $e($item['title']) ?></h3><?php endif;?><?php if(!empty($item['text'])):?><p><?= $e($item['text']) ?></p><?php endif;?></article><?php endforeach;?></div><?php endif;?><?= $action($data['cta_label']??'',$data['cta_url']??'') ?></div></section>
<?php endforeach;?>
